"""
bulwarkos_wifi.daemon — host-side WiFi bridge daemon.

Connects to the virtio-serial port exposed by the sys-net VM and registers
two D-Bus services on the session bus:

  org.bulwarkos.Wifi          — native interface for the CLI and panel
  org.freedesktop.NetworkManager — NM compatibility shim for DE applets

Start via:  python3 -m bulwarkos_wifi
"""

import json
import logging
import os
import queue
import select
import signal
import sys
import threading
import time

log = logging.getLogger(__name__)

try:
    import dbus
    import dbus.service
    import dbus.mainloop.glib
    from gi.repository import GLib
except ImportError:
    print(
        "Error: python3-dbus and python3-gobject are required.\n"
        "Install with: sudo dnf install python3-dbus python3-gobject3",
        file=sys.stderr,
    )
    sys.exit(1)

from . import VIRTIO_PORT, DBUS_NAME, DBUS_PATH, DBUS_IFACE
from .protocol import (
    CMD_PING, CMD_SCAN, CMD_LIST, CMD_CONNECT, CMD_DISCONNECT,
    CMD_STATUS, CMD_FORGET,
    EVENT_CONNECTED, EVENT_DISCONNECTED, EVENT_STATE_CHANGED,
    STATE_CONNECTED,
    NM_DEVICE_STATE_UNAVAILABLE, NM_DEVICE_STATE_DISCONNECTED,
    NM_DEVICE_STATE_ACTIVATED, NM_CONNECTIVITY_FULL, NM_CONNECTIVITY_NONE,
)


# ---------------------------------------------------------------------------
# Wire protocol client
# ---------------------------------------------------------------------------

class WireClient:
    """
    Manages the connection to the virtio-serial port.
    Handles request/response matching by command ID and routes
    unsolicited events to a registered callback.
    Reconnects automatically when sys-net stops and restarts.
    """

    def __init__(self):
        self._port       = None
        self._lock       = threading.Lock()
        self._pending: dict[int, queue.Queue] = {}
        self._next_id    = 1
        self._event_cb   = None
        self._connected  = False

    def set_event_callback(self, cb):
        self._event_cb = cb

    @property
    def is_connected(self) -> bool:
        return self._connected

    def start(self):
        t = threading.Thread(
            target=self._reader, name="wire-reader", daemon=True
        )
        t.start()

    def _open_port(self):
        while True:
            if os.path.exists(VIRTIO_PORT):
                try:
                    self._port      = open(VIRTIO_PORT, "r+b", buffering=0)
                    self._connected = True
                    log.info(f"Connected to {VIRTIO_PORT}")
                    return
                except OSError as e:
                    log.warning(f"Could not open {VIRTIO_PORT}: {e}")
            else:
                log.debug(f"Waiting for {VIRTIO_PORT} (sys-net running?)")
            time.sleep(3)

    def _reader(self):
        buf = b""
        while True:
            if not self._port:
                self._open_port()
                continue
            try:
                r, _, _ = select.select([self._port], [], [], 5.0)
                if not r:
                    continue
                chunk = self._port.read(4096)
                if not chunk:
                    log.warning("virtio-serial EOF — sys-net stopped?")
                    self._connected = False
                    self._port      = None
                    # Drain any pending requests
                    with self._lock:
                        for q in self._pending.values():
                            q.put({"ok": False, "msg": "sys-net disconnected"})
                        self._pending.clear()
                    time.sleep(3)
                    continue
                buf += chunk
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if "event" in obj:
                        if self._event_cb:
                            try:
                                ev = obj.pop("event")
                                GLib.idle_add(self._event_cb, ev, obj)
                            except Exception as e:
                                log.error(f"Event callback error: {e}")
                    elif "id" in obj:
                        cid = obj["id"]
                        with self._lock:
                            q = self._pending.pop(cid, None)
                        if q:
                            q.put(obj)
            except OSError as e:
                log.error(f"Read error: {e}")
                self._connected = False
                self._port      = None
                time.sleep(3)

    def send(self, cmd: str, timeout: float = 10.0, **kwargs) -> dict:
        if not self._port:
            return {"ok": False, "msg": "Not connected to sys-net"}

        with self._lock:
            cid           = self._next_id
            self._next_id += 1
            q: queue.Queue = queue.Queue()
            self._pending[cid] = q

        payload = json.dumps({"id": cid, "cmd": cmd, **kwargs}) + "\n"
        try:
            self._port.write(payload.encode())
            self._port.flush()
        except OSError as e:
            with self._lock:
                self._pending.pop(cid, None)
            return {"ok": False, "msg": str(e)}

        try:
            return q.get(timeout=timeout)
        except queue.Empty:
            with self._lock:
                self._pending.pop(cid, None)
            return {"ok": False, "msg": "Timeout"}


# ---------------------------------------------------------------------------
# Native D-Bus service — org.bulwarkos.Wifi
# ---------------------------------------------------------------------------

class BulwarkWifiService(dbus.service.Object):
    """
    Native D-Bus service. Used directly by the CLI, the BulwarkOS panel,
    and any BulwarkOS-specific clients.
    """

    def __init__(self, bus, wire: WireClient):
        super().__init__(bus, DBUS_PATH)
        self._wire     = wire
        self._networks: list[dict] = []
        wire.set_event_callback(self._on_event)

    def _on_event(self, event: str, payload: dict):
        if event == EVENT_CONNECTED:
            self.StateChanged(STATE_CONNECTED, payload.get("ssid", ""))
        elif event == EVENT_DISCONNECTED:
            self.StateChanged("disconnected", "")
        elif event == EVENT_STATE_CHANGED:
            self.StateChanged(payload.get("state", "unknown"), "")
        return False  # GLib.idle_add cleanup

    # ── Signals ───────────────────────────────────────────────────────────

    @dbus.service.signal(DBUS_IFACE, signature="ss")
    def StateChanged(self, state: str, ssid: str):
        pass

    @dbus.service.signal(DBUS_IFACE, signature="aa{sv}")
    def NetworksFound(self, networks):
        pass

    # ── Methods ───────────────────────────────────────────────────────────

    @dbus.service.method(DBUS_IFACE, in_signature="", out_signature="b")
    def Scan(self):
        resp = self._wire.send(CMD_SCAN)
        if resp.get("ok"):
            def _fetch_after_scan():
                time.sleep(4)
                resp2 = self._wire.send(CMD_LIST)
                if resp2.get("ok"):
                    self._networks = resp2.get("networks", [])
                    GLib.idle_add(
                        lambda: self.NetworksFound(self._as_dbus_networks())
                    )
            threading.Thread(target=_fetch_after_scan, daemon=True).start()
        return bool(resp.get("ok"))

    @dbus.service.method(DBUS_IFACE, in_signature="", out_signature="aa{sv}")
    def ListNetworks(self):
        resp = self._wire.send(CMD_LIST)
        if resp.get("ok"):
            self._networks = resp.get("networks", [])
        return self._as_dbus_networks()

    @dbus.service.method(DBUS_IFACE, in_signature="ss", out_signature="bs")
    def Connect(self, ssid: str, passphrase: str):
        kw = {"ssid": str(ssid)}
        if passphrase:
            kw["passphrase"] = str(passphrase)
        resp = self._wire.send(CMD_CONNECT, timeout=30.0, **kw)
        return bool(resp.get("ok")), str(resp.get("msg", ""))

    @dbus.service.method(DBUS_IFACE, in_signature="", out_signature="bs")
    def Disconnect(self):
        resp = self._wire.send(CMD_DISCONNECT)
        return bool(resp.get("ok")), str(resp.get("msg", ""))

    @dbus.service.method(DBUS_IFACE, in_signature="s", out_signature="bs")
    def Forget(self, ssid: str):
        resp = self._wire.send(CMD_FORGET, ssid=str(ssid))
        return bool(resp.get("ok")), str(resp.get("msg", ""))

    @dbus.service.method(DBUS_IFACE, in_signature="", out_signature="a{sv}")
    def Status(self):
        resp = self._wire.send(CMD_STATUS)
        return {
            "state":     dbus.String(resp.get("state", "unknown")),
            "ssid":      dbus.String(resp.get("ssid", "")),
            "connected": dbus.Boolean(resp.get("state") == STATE_CONNECTED),
            "proxy_ok":  dbus.Boolean(self._wire.is_connected),
        }

    def _as_dbus_networks(self):
        result = []
        for n in self._networks:
            result.append({
                "ssid":      dbus.String(n.get("ssid", "")),
                "security":  dbus.String(n.get("security", "open")),
                "connected": dbus.Boolean(n.get("connected", False)),
                "strength":  dbus.Int32(n.get("strength_dbm", -100)),
            })
        return result


# ---------------------------------------------------------------------------
# NetworkManager compatibility shim
# ---------------------------------------------------------------------------

_NM_IFACE       = "org.freedesktop.NetworkManager"
_NM_PATH        = "/org/freedesktop/NetworkManager"
_NM_DEVICE_PATH = "/org/freedesktop/NetworkManager/Devices/1"


class NMCompatShim(dbus.service.Object):
    """
    Minimal org.freedesktop.NetworkManager compatibility shim.
    Exposes enough surface that GNOME Shell, KDE Plasma, nm-applet,
    and other DE network widgets see a wireless device and can control it.
    """

    def __init__(self, bus, wifi_svc: BulwarkWifiService):
        super().__init__(bus, _NM_PATH)
        self._svc = wifi_svc
        wifi_svc.connect_to_signal("StateChanged", self._on_wifi_state)

    def _on_wifi_state(self, state: str, ssid: str):
        nm_state = (
            NM_DEVICE_STATE_ACTIVATED
            if state == STATE_CONNECTED
            else NM_DEVICE_STATE_DISCONNECTED
        )
        self.DeviceStateChanged(
            dbus.ObjectPath(_NM_DEVICE_PATH),
            dbus.UInt32(nm_state),
            dbus.UInt32(NM_DEVICE_STATE_DISCONNECTED),
            dbus.UInt32(0),
        )

    @dbus.service.signal(_NM_IFACE, signature="ouuu")
    def DeviceStateChanged(self, device, new_state, old_state, reason):
        pass

    @dbus.service.method(_NM_IFACE, in_signature="", out_signature="ao")
    def GetDevices(self):
        return [dbus.ObjectPath(_NM_DEVICE_PATH)]

    @dbus.service.method(_NM_IFACE, in_signature="", out_signature="ao")
    def GetAllDevices(self):
        return [dbus.ObjectPath(_NM_DEVICE_PATH)]

    @dbus.service.method(_NM_IFACE, in_signature="", out_signature="u")
    def CheckConnectivity(self):
        resp = self._svc._wire.send(CMD_STATUS)
        return dbus.UInt32(
            NM_CONNECTIVITY_FULL
            if resp.get("state") == STATE_CONNECTED
            else NM_CONNECTIVITY_NONE
        )

    @dbus.service.method(
        "org.freedesktop.DBus.Properties",
        in_signature="ss", out_signature="v",
    )
    def Get(self, iface, prop):
        if prop == "WirelessEnabled":
            return dbus.Boolean(True)
        if prop == "State":
            resp = self._svc._wire.send(CMD_STATUS)
            return dbus.UInt32(
                NM_DEVICE_STATE_ACTIVATED
                if resp.get("state") == STATE_CONNECTED
                else NM_DEVICE_STATE_DISCONNECTED
            )
        raise dbus.exceptions.DBusException(
            f"org.freedesktop.DBus.Error.InvalidArgs: Unknown property {prop}"
        )


# ---------------------------------------------------------------------------
# Daemon entry point
# ---------------------------------------------------------------------------

def run():
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [bulwarkos-wifi] %(levelname)s %(message)s",
        stream=sys.stderr,
    )

    dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)
    session_bus = dbus.SessionBus()
    bus_name    = dbus.service.BusName(DBUS_NAME, session_bus)

    wire = WireClient()
    wire.start()

    svc  = BulwarkWifiService(session_bus, wire)
    shim = NMCompatShim(session_bus, svc)

    log.info(f"D-Bus service: {DBUS_NAME}")
    log.info(f"Virtio port:   {VIRTIO_PORT}")
    log.info("Ready — waiting for sys-net")

    GLib.MainLoop().run()
